protected function legacyMoveAddressFields(&$rule)
{
    $fields = [];
    $fields['source'] = 'from';
    $fields['destination'] = 'to';
    $interfaces = $this->interfaceMapping;
    foreach ($fields as $tag => $target) {
        if (!empty($rule[$tag])) {
            if (!empty($rule[$tag]['network'])) {
                $rule[$target] = $rule[$tag]['network'];
